// The session-start check never follows a generated file to a NEW destination. Where the file
// is gets recorded when it is generated; before a repair the path must still be a plain file
// with no other name, in that same folder, inside the account folder. Everything runs in temp
// dirs with a fake home, on literal file contents.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {
  buildHome, acc, check, rmrf, write, read, json, exists, isLink, planAndApply, tmpDir, atomicSave, CAN_SYMLINK,
} from './accounts-fixture.mjs';
import { runCheck, summaryLine } from '../scripts/sync-check.mjs';

const OLD = 'old contents';
const NEW = 'new source';
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');

/**
 * A hand-written manifest, as the review used: the primary's CLAUDE.md is kept as a managed copy
 * at ~/.codex/AGENTS.md and at ~/.codex/docs/extra.md. Both copies hold OLD and are recorded
 * with that hash. The manifest has no `identity`: it is one written before identities existed.
 */
function crafted(t) {
  const root = tmpDir('hd-ident-');
  t.after(() => rmrf(root));
  const home = path.join(root, 'home');
  const claude = path.join(home, '.claude');
  const codex = path.join(home, '.codex');
  const src = path.join(claude, 'CLAUDE.md');
  const dst = path.join(codex, 'AGENTS.md');
  const sub = path.join(codex, 'docs', 'extra.md');
  for (const f of [src, dst, sub]) write(f, OLD);
  const element = (name, file) => ({ name, kind: 'generated', path: file, target: src, generator: { type: 'copy' }, sourceHash: sha256(OLD), contentHash: sha256(OLD) });
  const manifestFile = path.join(home, '.novarc-powers', 'novarc-harness-doctor', 'sync', 'manifest.json');
  write(manifestFile, JSON.stringify({
    version: 1, tool: 'novarc-harness-doctor', primary: 'claude-1', primaryPathAbs: claude,
    accounts: [{ id: 'codex-1', provider: 'codex', pathAbs: codex, mode: 'replicated', exceptions: [], elements: [element('AGENTS.md', dst), element('docs/extra.md', sub)] }],
  }, null, 2));
  const recorded = (name) => json(manifestFile).accounts[0].elements.find((e) => e.name === name);
  const run = (repair = true) => {
    const report = runCheck({ repair, home });
    return { report, line: summaryLine(report), el: (name) => report.accounts[0].elements.find((e) => e.name === name) };
  };
  return { root, home, claude, codex, src, dst, sub, recorded, run };
}

/** The same, after one healthy `--repair` run recorded where both files are. */
function recordedHome(t) {
  const c = crafted(t);
  assert.equal(c.run().report.status, 'ok');
  assert.equal(c.recorded('AGENTS.md').identity.type, 'file');
  return c;
}

test('identity: a first run records where a generated file is, only while it is provably the generated one', (t) => {
  const c = crafted(t);
  // Without --repair nothing is recorded.
  assert.equal(c.run(false).report.status, 'ok');
  assert.equal(c.recorded('AGENTS.md').identity, undefined);
  assert.equal(c.run().report.status, 'ok');
  const id = c.recorded('AGENTS.md').identity;
  assert.deepEqual({ type: id.type, parent: id.parent, real: id.real, nlink: id.nlink }, { type: 'file', parent: c.codex, real: c.dst, nlink: 1 });
  // Volume and file ids: decimal strings (a Windows file id does not fit a number).
  assert.match(id.dev, /^\d+$/);
  assert.match(id.ino, /^\d+$/);
  assert.equal(id.ino, String(fs.statSync(c.dst, { bigint: true }).ino));
  assert.deepEqual(c.recorded('docs/extra.md').identity.parent, path.join(c.codex, 'docs'));

  // A manifest with no identity, and a file that is out of date but still the generated bytes
  // at a link-free place: repaired, and recorded.
  const d = crafted(t);
  write(d.src, NEW);
  const r = d.run();
  assert.equal(r.line, 'novarc-harness-doctor account sync: repaired 2 (codex-1 AGENTS.md; codex-1 docs/extra.md).');
  assert.deepEqual([read(d.dst), read(d.sub)], [NEW, NEW]);
  assert.deepEqual([d.recorded('AGENTS.md').identity.type, d.recorded('AGENTS.md').identity.parent], ['file', d.codex]);
  assert.equal(d.recorded('AGENTS.md').contentHash, sha256(NEW));
});

test('identity: a generated file swapped for a hardlink to another file is never written through', (t) => {
  for (const make of [crafted, recordedHome]) { // with and without a recorded identity
    const c = make(t);
    const unrelated = path.join(c.root, 'unrelated.txt');
    write(unrelated, OLD);
    fs.rmSync(c.dst);
    fs.linkSync(unrelated, c.dst);
    write(c.src, NEW);
    for (const repair of [false, true, true]) {
      const r = c.run(repair);
      assert.deepEqual(r.el('AGENTS.md'), {
        name: 'AGENTS.md', state: 'drift', note: 'it now shares its content with another file (a hardlink); not rewritten', decide: true, path: '~/.codex/AGENTS.md', source: '~/.claude/CLAUDE.md',
      });
      assert.equal(read(unrelated), OLD, 'the repair wrote into the unrelated file');
      assert.equal(read(c.dst), OLD);
      assert.equal(fs.statSync(c.dst).nlink, 2);
      assert.ok(r.line.includes('(codex-1 AGENTS.md: it now shares its content with another file (a hardlink); not rewritten (~/.codex/AGENTS.md vs ~/.claude/CLAUDE.md)'), r.line);
      assert.match(r.line, /needs attention [12] \(/);
    }
    assert.equal(c.recorded('AGENTS.md').contentHash, sha256(OLD), 'a refused repair was recorded as done');
    // The other generated file of the same account is still repaired.
    assert.equal(read(c.sub), NEW);
    // Put a plain file back and the check takes over again.
    fs.rmSync(c.dst);
    write(c.dst, OLD);
    assert.equal(c.run().el('AGENTS.md').repaired, true);
    assert.deepEqual([read(c.dst), read(unrelated), fs.statSync(c.dst).nlink], [NEW, OLD, 1]);
  }
});

test('identity: a generated file swapped for a symbolic link is never written through', { skip: !CAN_SYMLINK && 'symbolic links cannot be created here' }, (t) => {
  for (const make of [crafted, recordedHome]) {
    const c = make(t);
    const unrelated = path.join(c.root, 'unrelated.txt');
    write(unrelated, OLD);
    fs.rmSync(c.dst);
    fs.symlinkSync(unrelated, c.dst, 'file');
    write(c.src, NEW);
    for (const repair of [false, true, true]) {
      const r = c.run(repair);
      assert.deepEqual(r.el('AGENTS.md'), {
        name: 'AGENTS.md', state: 'drift', note: 'it became a link to another place; not rewritten', decide: true, path: '~/.codex/AGENTS.md', source: '~/.claude/CLAUDE.md',
      });
      assert.equal(read(unrelated), OLD, 'the repair followed the link');
      assert.ok(isLink(c.dst), 'the link was replaced');
    }
    // A link that points nowhere is not replaced either.
    fs.rmSync(unrelated);
    const r = c.run();
    assert.deepEqual([r.el('AGENTS.md').state, r.el('AGENTS.md').note], ['broken', 'it became a link to another place; not rewritten']);
    assert.ok(isLink(c.dst) && !exists(unrelated));
  }
});

test('identity: a redirected folder above the file is never followed', (t) => {
  // 1. A sub-folder of the account now leads outside it.
  for (const make of [crafted, recordedHome]) {
    const c = make(t);
    const outside = path.join(c.root, 'outside-docs');
    write(path.join(outside, 'extra.md'), OLD);
    fs.rmSync(path.join(c.codex, 'docs'), { recursive: true });
    fs.symlinkSync(outside, path.join(c.codex, 'docs'), 'junction'); // a plain folder link outside Windows
    write(c.src, NEW);
    const r = c.run();
    assert.deepEqual(r.el('docs/extra.md'), {
      name: 'docs/extra.md', state: 'drift', note: 'its folder now leads outside the account folder; not rewritten', decide: true, path: '~/.codex/docs/extra.md', source: '~/.claude/CLAUDE.md',
    });
    assert.equal(read(path.join(outside, 'extra.md')), OLD, 'the repair followed the redirected folder');
    // A missing file is not re-created through the redirected folder either.
    fs.rmSync(path.join(outside, 'extra.md'));
    const gone = c.run();
    assert.deepEqual([gone.el('docs/extra.md').state, gone.el('docs/extra.md').note], ['broken', 'its folder now leads outside the account folder; not rewritten']);
    assert.deepEqual(fs.readdirSync(outside), []);
    assert.equal(read(c.dst), NEW, 'the file that did not move is still repaired');
  }

  // 2. The account folder itself was moved and replaced by a link to where it went.
  const c = recordedHome(t);
  const moved = path.join(c.root, 'codex-moved');
  fs.renameSync(c.codex, moved);
  fs.symlinkSync(moved, c.codex, 'junction');
  write(c.src, NEW);
  const r = c.run();
  assert.deepEqual([r.el('AGENTS.md').state, r.el('AGENTS.md').note, r.el('AGENTS.md').decide], ['drift', 'its folder now leads somewhere else; not rewritten', true]);
  assert.equal(read(path.join(moved, 'AGENTS.md')), OLD);

  // The same with a manifest that never recorded a place: it cannot be confirmed, so it is refused.
  const d = crafted(t);
  const moved2 = path.join(d.root, 'codex-moved');
  fs.renameSync(d.codex, moved2);
  fs.symlinkSync(moved2, d.codex, 'junction');
  write(d.src, NEW);
  const legacy = d.run();
  assert.equal(legacy.el('AGENTS.md').note, 'its place was never recorded and cannot be confirmed (plan and apply again); not rewritten');
  assert.equal(read(path.join(moved2, 'AGENTS.md')), OLD);
  assert.equal(d.recorded('AGENTS.md').identity, undefined, 'an unconfirmed place was recorded');
});

test('identity: a missing file is re-created, and a file replaced by an identical plain file is still repaired', (t) => {
  const c = recordedHome(t);
  fs.rmSync(c.dst);
  write(c.src, NEW);
  const r = c.run();
  assert.deepEqual([r.el('AGENTS.md').repaired, r.el('AGENTS.md').note], [true, 'the generated file was gone']);
  assert.equal(read(c.dst), NEW);
  // An editor or a sync tool saved the same bytes through a rename: another inode, the same
  // plain single-name file in the same folder. Not a reason to refuse.
  atomicSave(c.dst, NEW);
  assert.notEqual(c.recorded('AGENTS.md').identity.ino, String(fs.statSync(c.dst, { bigint: true }).ino), 'the fixture did not replace the file');
  write(c.src, 'newer source');
  assert.equal(c.run().el('AGENTS.md').repaired, true);
  assert.equal(read(c.dst), 'newer source');
  const id = c.recorded('AGENTS.md').identity;
  assert.deepEqual([id.type, id.nlink, id.parent], ['file', 1, c.codex]);
  assert.equal(id.ino, String(fs.statSync(c.dst, { bigint: true }).ino), 'the record does not follow the file that is there now');
  // A hand edit is still never overwritten.
  write(c.dst, 'typed by hand');
  write(c.src, 'newest source');
  assert.equal(c.run().el('AGENTS.md').note, 'edited by hand; not overwritten');
  assert.equal(read(c.dst), 'typed by hand');
});

const ALL = ['--resolve', 'claude-2:CLAUDE.md=replace-with-primary', '--resolve', 'claude-2:skills/=replace-with-primary', '--resolve', 'codex-1:AGENTS.md=replace-with-primary'];

function synced(t) {
  const h = buildHome();
  t.after(() => rmrf(h.root));
  const r = planAndApply(h, 'claude-1', ALL);
  assert.equal(r.apply.code, 0, r.apply.stdout + r.apply.stderr);
  return h;
}
const codexOf = (h) => json(path.join(h.sync, 'manifest.json')).accounts.find((a) => a.id === 'codex-1');

test('apply records the destination of what it generates, and the check refuses a swapped one until a plan decides', (t) => {
  const h = synced(t);
  const agents = path.join(h.codexDir, 'AGENTS.md');
  const toml = path.join(h.codexDir, 'config.toml');
  const id = codexOf(h).elements.find((e) => e.name === 'AGENTS.md').identity;
  assert.deepEqual({ type: id.type, parent: id.parent, real: id.real, nlink: id.nlink }, { type: 'file', parent: h.codexDir, real: agents, nlink: 1 });
  assert.match(id.ino, /^\d+$/);
  // The MCP file: no file id, because the app replaces that file whenever it saves.
  assert.deepEqual(codexOf(h).mcp.identity, { type: 'file', parent: h.codexDir, real: toml, nlink: 1 });

  // AGENTS.md becomes a second name of a file kept elsewhere, with the bytes that were generated.
  const elsewhere = path.join(h.root, 'elsewhere', 'notes.md');
  write(elsewhere, read(agents));
  const generated = read(agents);
  fs.rmSync(agents);
  fs.linkSync(elsewhere, agents);
  fs.appendFileSync(path.join(h.claude, 'RTK.md'), '\nA rule added later. LATER-RULE\n');
  for (let i = 0; i < 2; i++) {
    const r = check(h.home, ['--repair']);
    assert.equal(r.code, 0);
    assert.match(r.stdout, /needs attention 1 \(codex-1 AGENTS\.md: it now shares its content with another file \(a hardlink\); not rewritten \(~\/\.codex\/AGENTS\.md vs ~\/\.claude\/CLAUDE\.md\)\)/);
    assert.equal(read(elsewhere), generated, 'the check wrote into the file kept elsewhere');
  }
  // The plan shows it as a conflict instead of regenerating through the link.
  const diff = acc(h.home, ['diff']).json.accounts.find((a) => a.id === 'codex-1').sync.elements.find((e) => e.name === 'AGENTS.md');
  assert.deepEqual(diff, { name: 'AGENTS.md', state: 'divergent', note: 'a generated file that is now a link, shares its content with another file, or sits behind a redirected folder' });
  const plan = acc(h.home, ['plan', '--primary', 'claude-1']).json;
  const conflict = plan.conflicts.find((c) => c.account === 'codex-1' && c.element === 'AGENTS.md');
  assert.deepEqual([conflict.state, conflict.options, conflict.choice], ['divergent', ['keep-as-exception', 'replace-with-primary'], 'keep-as-exception']);
  // Decided: the swapped name goes to the backup, a plain file is generated, the other file stays.
  const fix = planAndApply(h, 'claude-1', ['--resolve', 'codex-1:AGENTS.md=replace-with-primary']);
  assert.equal(fix.apply.code, 0, fix.apply.stdout);
  assert.equal(read(elsewhere), generated);
  assert.equal(fs.statSync(agents).nlink, 1);
  assert.ok(read(agents).includes('A rule added later. LATER-RULE\n'));
  assert.equal(read(path.join(h.sync, 'backups', fix.apply.json.stamp, 'codex-1', 'AGENTS.md')), generated);
  assert.equal(check(h.home, ['--repair']).stdout, '');
});

test('the check does not write a config.toml that became a second name of another file', (t) => {
  const h = synced(t);
  const toml = path.join(h.codexDir, 'config.toml');
  const other = path.join(h.root, 'elsewhere', 'other.toml');
  write(other, read(toml));
  const original = read(toml);
  fs.rmSync(toml);
  fs.linkSync(other, toml);
  const state = JSON.parse(read(h.state1));
  state.mcpServers.context7.args = ['-y', 'context7-mcp@2'];
  fs.writeFileSync(h.state1, JSON.stringify(state, null, 2) + '\n');

  for (const args of [['check'], ['check', '--repair'], ['check', '--repair']]) {
    const el = acc(h.home, args).json.accounts.find((a) => a.id === 'codex-1').elements.find((e) => e.name === 'mcp servers/context7');
    assert.deepEqual(el, {
      name: 'mcp servers/context7', state: 'drift', manual: true, path: '~/.codex/config.toml', source: '~/.claude.json',
      note: 'the primary changed; the account file is not written here: it now shares its content with another file (a hardlink)',
    });
    assert.deepEqual([read(other), read(toml)], [original, original], 'the check wrote through the hardlink');
  }
  assert.match(check(h.home, ['--repair']).stdout, /codex-1: 1 MCP server behind the primary \(run accounts\.mjs plan, then apply with the app closed\)/);
  // A plain file again: the check repairs it as before.
  fs.rmSync(toml);
  write(toml, original);
  assert.match(check(h.home, ['--repair']).stdout, /repaired 1 \(codex-1 mcp servers\/context7\)/);
  assert.ok(read(toml).includes('args = ["-y", "context7-mcp@2"]\n'));
  assert.equal(read(other), original);
});
